(() => {
  const root=document.querySelector('[data-my-franklin]'); if(!root)return;
  const es=document.documentElement.lang==='es';
  const prefKey='franklinNavigator.myFranklin.v1', reminderKey='franklinNavigator.reminders.v1', savedProfileKey='franklinNavigator.savedProfiles.v1';
  const form=root.querySelector('form:not([data-franklin-reminder-form])'), output=root.querySelector('[data-my-franklin-output]'), status=root.querySelector('[data-my-franklin-status]'), clear=root.querySelector('[data-my-franklin-clear]');
  const reminderForm=root.querySelector('[data-franklin-reminder-form]'), reminderList=root.querySelector('[data-franklin-reminders]'), savedList=root.querySelector('[data-saved-profiles]');
  const routes={
    newcomer:[es?'Nuevo en Franklin':'New to Franklin','/new-to-franklin/'], homeowner:[es?'Casa y propiedad':'Home & property','/home-property-help/'], renter:[es?'Vivienda y alquiler':'Housing & renter starting help','/housing/'], children:[es?'Escuelas y familia':'Schools & family','/school-enrollment/'], caregiver:[es?'Personas mayores y cuidado':'Senior & caregiving','/local-pathways/seniors-caregiving/'], transit:[es?'Transporte y movilidad':'Transportation & mobility','/getting-around/'], business:[es?'Para negocios':'For Business','/business-dashboard/'], civic:[es?'Vida cívica y vecindario':'Civic & neighborhood','/local-pathways/civic-neighborhood/'], events:[es?'Hoy y eventos locales':'Today & local events','/today/'], jobs:[es?'Empleo y carrera':'Jobs & career','/local-pathways/jobs-career/'], parks:[es?'Parques y comunidad':'Parks & community','/community/']
  };
  const t={
    heading:es?'Sus puntos de partida en Franklin':'Your Franklin starting points', choose:es?'Elija lo que le importa y guárdelo solamente en este dispositivo para crear un panel más corto.':'Choose what matters to you and save it on this device to build a shorter personal dashboard.', keep:es?'Mantenga este tema de Franklin a mano.':'Keep this Franklin topic close at hand.', open:es?'Abrir':'Open', today:es?'Ver lo importante hoy':'See what matters today', ask:es?'Preguntar al Navegador':'Ask Navigator', none:es?'Todavía no hay recordatorios locales guardados.':'No local reminders saved yet.', remove:es?'Quitar':'Remove', loaded:es?'Preferencias guardadas cargadas desde este dispositivo.':'Saved preferences loaded from this device.', saved:es?'Guardado solamente en este dispositivo. No se envió nada a Franklin Navigator.':'Saved on this device only. Nothing was sent to Franklin Navigator.', cleared:es?'Las preferencias, recordatorios y perfiles guardados se eliminaron de este dispositivo.':'Saved Franklin preferences, reminders and profiles were removed from this device.', noProfiles:es?'Todavía no hay perfiles locales guardados.':'No local profiles saved yet.', savedProfile:es?'Perfil público guardado solamente en este dispositivo.':'Public profile saved on this device only.', duplicateProfile:es?'Este perfil ya estaba guardado en este dispositivo.':'This profile was already saved on this device.', profileLimit:es?'Puede guardar hasta 25 perfiles. Quite uno antes de guardar otro.':'You can save up to 25 profiles. Remove one before saving another.', viewProfile:es?'Ver perfil':'View profile', checked:es?'Revisado':'Checked'
  };
  const safeParse=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}};
  const readPrefs=()=>safeParse(prefKey,null); const readReminders=()=>{const v=safeParse(reminderKey,[]);return Array.isArray(v)?v:[]}; const saveReminders=v=>localStorage.setItem(reminderKey,JSON.stringify(v.slice(0,25)));
  const readProfiles=()=>{const v=safeParse(savedProfileKey,[]);return Array.isArray(v)?v.filter(row=>row&&/^[-A-Za-z0-9._~]+$/.test(String(row.id||''))).slice(0,25):[]}; const saveProfiles=v=>localStorage.setItem(savedProfileKey,JSON.stringify(v.slice(0,25)));
  const render=data=>{output.replaceChildren();const selected=data?.interests||[];const heading=document.createElement('h2');heading.textContent=t.heading;output.append(heading);if(!selected.length){const p=document.createElement('p');p.textContent=t.choose;output.append(p);return}const grid=document.createElement('div');grid.className='grid three';for(const id of selected){if(!routes[id])continue;const [label,href]=routes[id];const card=document.createElement('article');card.className='card';const h=document.createElement('h3');h.textContent=label;const p=document.createElement('p');p.textContent=t.keep;const a=document.createElement('a');a.href=href;a.textContent=t.open;card.append(h,p,a);grid.append(card)}output.append(grid);const today=document.createElement('p');today.innerHTML=`<a class="button primary" href="${es?'/es/hoy/':'/today/'}">${t.today}</a> <a class="button" href="${es?'/es/':'/#ask-navigator'}">${t.ask}</a>`;output.append(today)};
  const renderReminders=()=>{if(!reminderList)return;reminderList.replaceChildren();const items=readReminders().sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.createdAt.localeCompare(b.createdAt));if(!items.length){const p=document.createElement('p');p.className='empty-state';p.textContent=t.none;reminderList.append(p);return}const list=document.createElement('ul');list.className='reminder-list';for(const item of items){const li=document.createElement('li');const text=document.createElement('span');text.textContent=item.date?`${item.label} — ${item.date}`:item.label;const remove=document.createElement('button');remove.type='button';remove.className='button small';remove.textContent=t.remove;remove.addEventListener('click',()=>{saveReminders(readReminders().filter(row=>row.id!==item.id));renderReminders()});li.append(text,remove);list.append(li)}reminderList.append(list)};
  const renderProfiles=()=>{if(!savedList)return;savedList.replaceChildren();const items=readProfiles();if(!items.length){const p=document.createElement('p');p.className='empty-state';p.textContent=t.noProfiles;savedList.append(p);return}const grid=document.createElement('div');grid.className='grid three';for(const item of items){const card=document.createElement('article');card.className='card saved-profile-card';const h=document.createElement('h3');h.textContent=item.name;const facts=document.createElement('p');facts.textContent=[item.category,item.location,item.checked?`${t.checked} ${item.checked}`:''].filter(Boolean).join(' · ');const actions=document.createElement('div');actions.className='actions';const view=document.createElement('a');view.className='button small';view.href=`/profiles/${encodeURIComponent(item.id)}/`;view.textContent=t.viewProfile;const remove=document.createElement('button');remove.type='button';remove.className='button small';remove.textContent=t.remove;remove.addEventListener('click',()=>{saveProfiles(readProfiles().filter(row=>row.id!==item.id));renderProfiles()});actions.append(view,remove);card.append(h,facts,actions);grid.append(card)}savedList.append(grid)};
  const load=data=>{if(!data)return;form.querySelectorAll('input[name="interests"]').forEach(input=>input.checked=(data.interests||[]).includes(input.value));const area=form.elements.area;if(area)area.value=data.area||'franklin';render(data);status.textContent=t.loaded};
  const importProfile=async()=>{const params=new URLSearchParams(location.search),id=params.get('saveProfile'),chunk=Number(params.get('chunk'));if(!id)return;if(!/^[-A-Za-z0-9._~]+$/.test(id)||!Number.isInteger(chunk)||chunk<1||chunk>20){history.replaceState(null,'',location.pathname);return}try{const response=await fetch(`/data/franklin-profiles-${String(chunk).padStart(2,'0')}.json`,{credentials:'same-origin'});if(!response.ok)throw new Error('profile unavailable');const payload=await response.json(),row=payload.records?.find(item=>item.i===id);if(!row)throw new Error('profile missing');const items=readProfiles(),existing=items.find(item=>item.id===id);if(existing){status.textContent=t.duplicateProfile}else if(items.length>=25){status.textContent=t.profileLimit}else{items.unshift({id:row.i,name:row.n,category:String(row.c||row.t||'').replace(/[_-]+/g,' '),location:row.l||'Franklin area',checked:row.d||'',savedAt:new Date().toISOString()});saveProfiles(items);status.textContent=t.savedProfile}renderProfiles()}catch{status.textContent=es?'No se pudo guardar ese perfil. Vuelva al directorio e inténtelo de nuevo.':'That profile could not be saved. Return to the directory and try again.'}finally{history.replaceState(null,'',location.pathname)}};
  form.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(form),data={area:String(fd.get('area')||'franklin'),interests:fd.getAll('interests').map(String),savedAt:new Date().toISOString()};localStorage.setItem(prefKey,JSON.stringify(data));render(data);status.textContent=t.saved});
  clear.addEventListener('click',()=>{localStorage.removeItem(prefKey);localStorage.removeItem(reminderKey);localStorage.removeItem(savedProfileKey);form.reset();render(null);renderReminders();renderProfiles();status.textContent=t.cleared});
  if(reminderForm)reminderForm.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(reminderForm),label=String(fd.get('label')||'').trim().replace(/\s+/g,' ').slice(0,120),date=String(fd.get('date')||'');if(!label)return;const items=readReminders();items.push({id:`r-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,label,date:/^\d{4}-\d{2}-\d{2}$/.test(date)?date:'',createdAt:new Date().toISOString()});saveReminders(items);reminderForm.reset();renderReminders()});
  const prefs=readPrefs();load(prefs);if(!prefs)render(null);renderReminders();renderProfiles();importProfile();
})();
